# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List, Sequence, Tuple

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def check_students(students: Sequence[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for student in students:
        if not (student.email or "").strip():
            raise ProjectError(
                f"no email for {student.display_name}"
            )


def name_key(student: Student) -> Tuple[str, str, str]:
    return (
        student.last_name.lower(),
        student.first_name.lower(),
        student.student_id
    )


def cell_row(student: Student) -> tuple:
    return (
        student.display_name,
        student.section,
        student.email.strip()
    )


def cell_rows(students: Sequence[Student]) -> List[tuple]:
    ordered = sorted(students, key=name_key)
    return [cell_row(item) for item in ordered]


def pad_row(cells: tuple, widths: List[int]) -> str:
    padded = [
        text.ljust(size)
        for text, size in zip(cells, widths)
    ]
    return "  ".join(padded).rstrip()


def format_contacts(
    students: Sequence[Student]
) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    check_students(students)
    cells = cell_rows(students)
    widths = [max(map(len, line)) for line in zip(*cells)]
    return [pad_row(item, widths) for item in cells]
